sys_script.script:
/**
 * 22b-Car unavailable for selected dates
 *
 * Blocks the reservation when the selected Car has a Car Unavailability window
 * that overlaps the requested rental dates.
 *
 * Only evaluated when the car or either date is set or changed - the same guard
 * pattern rule 22 uses - so a reservation that is already on the books can
 * still be closed or cancelled after its car goes out of service. Without the
 * guard, a car going into the workshop would trap its existing bookings in the
 * "reserved" state for ever.
 */
(function executeRule(/** @type {any} */ current, /** @type {any} */ previous) {
    if (!current.car.changes() && !current.start_date.changes() && !current.end_date.changes()) {
        return;
    }

    var carId = current.getValue('car');
    var startDate = current.getValue('start_date');
    if (!carId || !startDate) {
        return;
    }

    // A booking with a start date but no end date is a single-day rental, so
    // the window collapses to that one day. Leaving end empty must not turn the
    // overlap test into "no upper bound", which would match every outage.
    var endDate = current.getValue('end_date') || startDate;

    // Standard inclusive overlap test: two date ranges overlap when each one
    // starts on or before the other one ends.
    var unavailable = new GlideRecord('x_2203703_car_re_0_car_unavail');
    unavailable.addQuery('car', carId);
    unavailable.addQuery('start_date', '<=', endDate);
    unavailable.addQuery('end_date', '>=', startDate);
    unavailable.orderBy('start_date');
    unavailable.setLimit(1);
    unavailable.query();

    if (!unavailable.next()) {
        return;
    }

    var carName = current.getDisplayValue('car');
    var reason = unavailable.getDisplayValue('reason');

    gs.addErrorMessage(
        'The car "' +
            carName +
            '" is out of service from ' +
            unavailable.getValue('start_date') +
            ' to ' +
            unavailable.getValue('end_date') +
            ' (' +
            reason +
            ') and cannot be reserved for ' +
            startDate +
            ' to ' +
            endDate +
            '.'
    );
    current.setAbortAction(true);
})(current, previous);
